root.command:

IF COL_LENGTH(N'dbo.MobileDeliveryProofTbl', N'Reason') IS NULL
    ALTER TABLE dbo.MobileDeliveryProofTbl ADD Reason NVARCHAR(100) NULL;
IF COL_LENGTH(N'dbo.MobileDeliveryProofTbl', N'MissingItems') IS NULL
    ALTER TABLE dbo.MobileDeliveryProofTbl ADD MissingItems NVARCHAR(1000) NULL;
